  headFontFace: 'Aptos Display',
  bodyFontFace: 'Aptos',
  lang: 'en-US'
};
pptx.defineLayout({ name: 'CUSTOM_WIDE', width: 10, height: 5.625 });
pptx.layout = 'CUSTOM_WIDE';
pptx.margin = 0;
pptx.version = '2024';

const W = 10;
const H = 5.625;
const assetDir = '/app/benchmark/assets';
const outFile = '/app/output/final_deck.pptx';

const C = {
  navy: '071326',
  navy2: '0B1F3A',
  panel: '102A43',
  panel2: '0E2238',
  line: '234963',
  orange: 'F38020',
  orange2: 'FFB347',
  cyan: '36C5F0',
  green: '4BD37B',
  red: 'FF6B6B',
  purple: 'A78BFA',
  yellow: 'FFD166',
  white: 'F8FAFC',
  muted: 'A9BDD1',
  dim: '6E8AA6'
};

function img(name) { return path.join(assetDir, name); }
function safeImage(name) { const p = img(name); return fs.existsSync(p) ? p : null; }
function addBg(slide, opts = {}) {
  slide.background = { color: C.navy };
  slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: W, h: H, fill: { color: C.navy }, line: { color: C.navy, transparency: 100 } });
  slide.addShape(pptx.ShapeType.rect, { x: 0, y: 0, w: W, h: H, fill: { color: C.navy2, transparency: 16 }, line: { color: C.navy2, transparency: 100 } });
  slide.addShape(pptx.ShapeType.arc, { x: 7.15, y: -1.2, w: 4.1, h: 4.1, adjustPoint: 0.35, line: { color: C.orange, transparency: 86, pt: 2 }, rotate: 45 });
  slide.addShape(pptx.ShapeType.arc, { x: -1.0, y: 3.45, w: 3.1, h: 3.1, adjustPoint: 0.25, line: { color: C.cyan, transparency: 88, pt: 1.5 }, rotate: -30 });
  for (let i = 0; i < 7; i++) {
    slide.addShape(pptx.ShapeType.line, { x: 0.25 + i * 1.55, y: 5.34, w: 0.55, h: 0, line: { color: i % 2 ? C.cyan : C.orange, transparency: 55, pt: 1 } });
  }
  if (!opts.noFooter) addFooter(slide, opts.num || '');
}
function addFooter(slide, num) {
  slide.addText('Cloudflare Radar 2024 Year in Review', { x: 0.38, y: 5.27, w: 3.8, h: 0.15, fontFace: 'Aptos', fontSize: 6.8, color: C.dim, margin: 0 });
  slide.addText(String(num).padStart(2, '0'), { x: 9.25, y: 5.19, w: 0.38, h: 0.18, fontFace: 'Aptos', fontSize: 8.5, bold: true, color: C.orange, align: 'right', margin: 0 });
}
function addTitle(slide, title, kicker, num) {
  addBg(slide, { num });
  if (kicker) slide.addText(kicker.toUpperCase(), { x: 0.45, y: 0.28, w: 3.8, h: 0.15, fontSize: 7.3, bold: true, color: C.orange, charSpace: 1.1, margin: 0 });
  slide.addText(title, { x: 0.45, y: 0.48, w: 8.95, h: 0.55, fontFace: 'Aptos Display', fontSize: 20, bold: true, color: C.white, fit: 'shrink', breakLine: false, margin: 0.02 });
  slide.addShape(pptx.ShapeType.line, { x: 0.45, y: 1.12, w: 9.1, h: 0, line: { color: C.line, pt: 1 } });
}
function addPill(slide, text, x, y, w, color = C.orange) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h: 0.24, rectRadius: 0.06, fill: { color, transparency: 8 }, line: { color, transparency: 30, pt: 0.5 } });
  slide.addText(text, { x: x + 0.08, y: y + 0.055, w: w - 0.16, h: 0.08, fontSize: 6.8, bold: true, color: C.white, align: 'center', margin: 0 });
}
function addMetricCard(slide, x, y, w, h, value, label, color = C.orange, note = '') {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.06, fill: { color: C.panel, transparency: 5 }, line: { color: C.line, transparency: 35, pt: 0.8 } });
  slide.addText(value, { x: x + 0.16, y: y + 0.16, w: w - 0.32, h: 0.42, fontFace: 'Aptos Display', fontSize: 23, bold: true, color, margin: 0, fit: 'shrink' });
  slide.addText(label, { x: x + 0.17, y: y + 0.68, w: w - 0.34, h: 0.28, fontSize: 8.5, bold: true, color: C.white, margin: 0, fit: 'shrink' });
  if (note) slide.addText(note, { x: x + 0.17, y: y + 1.02, w: w - 0.34, h: h - 1.08, fontSize: 6.8, color: C.muted, margin: 0.01, fit: 'shrink' });
}
function addSectionLabel(slide, text, x, y, w) {
  slide.addText(text.toUpperCase(), { x, y, w, h: 0.16, fontSize: 7, bold: true, color: C.orange2, charSpace: 0.65, margin: 0 });
}
function addBullets(slide, items, x, y, w, h, fs = 9.2) {
  slide.addText(items.map(t => ({ text: t, options: { bullet: { type: 'bullet' }, breakLine: true } })), {
    x, y, w, h, fontFace: 'Aptos', fontSize: fs, color: C.white, breakLine: false, valign: 'top', fit: 'shrink', paraSpaceAfterPt: 6, margin: 0.01,
    breakLine: false
  });
}
function roundedPanel(slide, x, y, w, h, fill = C.panel, trans = 7) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.05, fill: { color: fill, transparency: trans }, line: { color: C.line, transparency: 32, pt: 0.7 } });
}
function cover() {
  const slide = pptx.addSlide();
