  slide.addShape(pptx.ShapeType.arc, { x: 6.3, y: -0.6, w: 4.4, h: 4.4, adjustPoint: 0.34, line: { color: C.orange, transparency: 45, pt: 4 }, rotate: 35 });
  slide.addShape(pptx.ShapeType.arc, { x: 6.85, y: -0.05, w: 3.25, h: 3.25, adjustPoint: 0.44, line: { color: C.cyan, transparency: 58, pt: 2 }, rotate: 35 });
  slide.addText('CLOUDFLARE RADAR', { x: 0.6, y: 0.48, w: 2.4, h: 0.16, fontSize: 7.2, bold: true, color: C.orange, charSpace: 1.2, margin: 0 });
  slide.addText('Cloudflare Radar 2024 Year in Review', { x: 0.58, y: 1.03, w: 5.85, h: 1.2, fontFace: 'Aptos Display', fontSize: 34, bold: true, color: C.white, fit: 'shrink', margin: 0 });
  slide.addShape(pptx.ShapeType.line, { x: 0.6, y: 2.42, w: 2.1, h: 0, line: { color: C.orange, pt: 2.1 } });
  slide.addText('A data-driven analysis of global Internet traffic, adoption trends, connectivity disruptions, and security threats observed through Cloudflare’s network in 2024.', { x: 0.62, y: 2.72, w: 5.45, h: 0.64, fontSize: 13.5, color: C.muted, fit: 'shrink', margin: 0.01, breakLine: false });
  addMetricCard(slide, 6.75, 2.72, 1.23, 1.1, '17%', 'Traffic growth', C.orange, 'YoY global Internet traffic');
  addMetricCard(slide, 8.13, 2.72, 1.23, 1.1, '225', 'Disruptions', C.cyan, 'Major outages observed');
  addMetricCard(slide, 6.75, 4.0, 1.23, 1.1, '6.5%', 'Mitigated', C.red, 'All traffic processed');
  addMetricCard(slide, 8.13, 4.0, 1.23, 1.1, '13%', 'PQ TLS 1.3', C.green, 'Up from ~2%');
  slide.addText('Audience: Technology executives and network infrastructure leaders', { x: 0.62, y: 4.84, w: 4.7, h: 0.18, fontSize: 7.8, color: C.dim, margin: 0 });
  addFooter(slide, '01');
}
function slide2() {
  const s = pptx.addSlide();
  addTitle(s, "17% Global Traffic Growth and Starlink's 3.3x Surge", 'Global traffic growth', '02');
  addMetricCard(s, 0.45, 1.35, 1.75, 1.27, '17%', 'Global Internet traffic growth', C.orange, 'Year-over-year increase in 2024');
  addMetricCard(s, 0.45, 2.84, 1.75, 1.27, '3.3x', 'Starlink traffic surge', C.cyan, 'Scaled normalized request volume');
  addSectionLabel(s, 'Executive signal', 0.48, 4.35, 1.5);
  s.addText('Demand expansion continues across communication, commerce, entertainment, and transportation; satellite networks add reach in underserved regions.', { x: 0.48, y: 4.57, w: 2.15, h: 0.46, fontSize: 7.7, color: C.muted, fit: 'shrink', margin: 0 });
