  s.addText('Generative AI continued its rapid rise throughout 2024, while the Metaverse receded into the background. Ranking methodology is based on aggregate data from Cloudflare’s 1.1.1.1 DNS resolver.', { x: 5.38, y: 4.38, w: 3.85, h: 0.42, fontSize: 8.3, color: C.white, fit: 'shrink', margin: 0 });
